<?php
require 'config.php';require_admin();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=(int)($_POST['id']??0);if($id){if($_POST['password']!==''){db()->prepare("UPDATE users SET name=?,email=?,role=?,status=?,password_hash=? WHERE id=?")->execute([$_POST['name'],$_POST['email'],$_POST['role'],$_POST['status'],password_hash($_POST['password'],PASSWORD_DEFAULT),$id]);}else{db()->prepare("UPDATE users SET name=?,email=?,role=?,status=? WHERE id=?")->execute([$_POST['name'],$_POST['email'],$_POST['role'],$_POST['status'],$id]);}}else{if(strlen($_POST['password'])<10)throw new RuntimeException('Password must be at least 10 characters.');db()->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,?)")->execute([$_POST['name'],$_POST['email'],password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role'],$_POST['status']]);}flash('success','User account saved.');redirect('users.php');}catch(Throwable $e){$error=$e->getMessage();}}
if(isset($_GET['toggle'])){db()->prepare("UPDATE users SET status=IF(status='Active','Inactive','Active') WHERE id=? AND id<>?")->execute([(int)$_GET['toggle'],current_user()['id']]);flash('success','User status updated.');redirect('users.php');}
$rows=db()->query("SELECT id,name,email,role,status,created_at FROM users ORDER BY id")->fetchAll();$pageTitle='User Accounts';$active='users';require 'partials_header.php';?>
<div class="page-head"><div><h1>User accounts</h1><p>Manage administrator and employee access. Only administrators can access this page.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="form-card" style="margin-bottom:20px"><h3>Create user account</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Temporary password (min 10 chars)</label><input type="password" name="password" required minlength="10"></div><div class="field"><label>Role</label><select name="role" required><option value="Admin">Administrator</option><option value="Dispatcher">Dispatcher</option><option value="Accounts">Accounts</option><option value="Viewer">Viewer</option></select></div><div class="field"><label>Status</label><select name="status"><option>Active</option><option>Inactive</option></select></div></div><div class="form-actions"><button class="btn primary">Create account</button></div></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td><td><a href="?toggle=<?=$r['id']?>" onclick="return confirm('Change user status?')">Toggle status</a></td></tr><?php endforeach;?></tbody></table></div><?php require 'partials_footer.php';?>